require __DIR__ . '/../lib/bootstrap.php';$token=(string)($_GET['token']??'');if($token==='')fail('Invitation token required');$st=db()->prepare('SELECT gi.id,gi.chat_id,gi.requires_approval,gi.expires_at,gi.max_uses,gi.use_count,c.name,c.group_category,c.retention_seconds FROM group_invites gi JOIN chats c ON c.id=gi.chat_id WHERE gi.token_hash=SHA2(?,256) AND gi.active=1 LIMIT 1');$st->execute([$token]);$i=$st->fetch();if(!$i)fail('Invalid or disabled invitation',404);if($i['expires_at']&&strtotime($i['expires_at'])<time())fail('Invitation expired',410);if($i['max_uses']!==null&&(int)$i['use_count']>=(int)$i['max_uses'])fail('Invitation usage limit reached',410);out(['group'=>['id'=>(int)$i['chat_id'],'name'=>$i['name'],'group_category'=>$i['group_category'],'retention_seconds'=>(int)$i['retention_seconds'],'requires_approval'=>(bool)$i['requires_approval']]]);
